/**
 * @summary Get walking route history for a user
 */
export const getGetRouteHistoryUrl = (params: GetRouteHistoryParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/routes/history?${stringifiedParams}`
    : `/api/routes/history`;
};

export const getRouteHistory = async (
  params: GetRouteHistoryParams,
  options?: RequestInit,
): Promise<WalkingRoute[]> => {
  return customFetch<WalkingRoute[]>(getGetRouteHistoryUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetRouteHistoryQueryKey = (params?: GetRouteHistoryParams) => {
  return [`/api/routes/history`, ...(params ? [params] : [])] as const;
};

export const getGetRouteHistoryQueryOptions = <
  TData = Awaited<ReturnType<typeof getRouteHistory>>,
  TError = ErrorType<unknown>,
>(
  params: GetRouteHistoryParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getRouteHistory>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetRouteHistoryQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getRouteHistory>>> = ({
    signal,
  }) => getRouteHistory(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getRouteHistory>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetRouteHistoryQueryResult = NonNullable<
  Awaited<ReturnType<typeof getRouteHistory>>
>;
export type GetRouteHistoryQueryError = ErrorType<unknown>;

/**
 * @summary Get walking route history for a user
 */

export function useGetRouteHistory<
  TData = Awaited<ReturnType<typeof getRouteHistory>>,
  TError = ErrorType<unknown>,
>(
  params: GetRouteHistoryParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getRouteHistory>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetRouteHistoryQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

